package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	if !sc.Scan() {
		return
	}
	var c int
	fmt.Sscan(strings.TrimSpace(sc.Text()), &c)
	var keys []int // most recent first
	vals := map[int]int{}
	touch := func(k int) {
		for i, x := range keys {
			if x == k {
				keys = append(keys[:i], keys[i+1:]...)
				break
			}
		}
		keys = append([]int{k}, keys...)
	}
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) == 0 {
			continue
		}
		switch f[0] {
		case "put":
			var k, v int
			fmt.Sscan(f[1], &k)
			fmt.Sscan(f[2], &v)
			vals[k] = v
			touch(k)
			if len(keys) > c {
				e := keys[len(keys)-1]
				keys = keys[:len(keys)-1]
				delete(vals, e)
				fmt.Fprintf(out, "evict %d\n", e)
			}
		case "get":
			var k int
			fmt.Sscan(f[1], &k)
			if v, ok := vals[k]; ok {
				touch(k)
				fmt.Fprintln(out, v)
			} else {
				fmt.Fprintln(out, -1)
			}
		case "keys":
			if len(keys) == 0 {
				fmt.Fprintln(out, "<empty>")
			} else {
				s := make([]string, len(keys))
				for i, k := range keys {
					s[i] = fmt.Sprint(k)
				}
				fmt.Fprintln(out, strings.Join(s, " "))
			}
		}
	}
}

